WITH p AS (SELECT p.object_id AS id, substr(json_extract_string(p.state,'$.date'), 1, 7) AS month, json_extract_string(a.state,'$.type') AS typ, CASE WHEN json_extract_string(p.state,'$.side') = 'debit' THEN CAST(json_extract(p.state,'$.amount') AS BIGINT) ELSE -CAST(json_extract(p.state,'$.amount') AS BIGINT) END AS b FROM objects p JOIN objects a ON json_extract_string(p.state,'$.account') = a.object_id WHERE p.object_type = 'posting' AND a.object_type = 'account' AND COALESCE(json_extract_string(p.state,'$.book'), 'main') = 'pl-stat' AND json_extract_string(a.state,'$.type') IN ('revenue', 'expense')) SELECT month, op, line, amount, o AS _of FROM (SELECT month, 1 AS k, '' AS op, 'Przychody' AS line, -COALESCE(SUM(b) FILTER (WHERE typ = 'revenue'), 0) AS amount, string_agg(id, ',' ORDER BY id) FILTER (WHERE typ = 'revenue') AS o FROM p GROUP BY month UNION ALL SELECT month, 2, '-', 'Koszty', COALESCE(SUM(b) FILTER (WHERE typ = 'expense'), 0), string_agg(id, ',' ORDER BY id) FILTER (WHERE typ = 'expense') FROM p GROUP BY month UNION ALL SELECT month, 3, '=', 'Wynik przed opodatkowaniem', -SUM(b), string_agg(id, ',' ORDER BY id) FROM p GROUP BY month) ORDER BY month, k
